css:
@font-face{font-family:"Bricolage";src:url(/schrift.woff2) format("woff2");font-weight:200 800;font-display:swap}
:root{--grund:#edf2f3;--flaeche:#fff;--tinte:#0f2730;--leise:#566b73;--linie:#d6e0e3;
--blau:#0a6c87;--blau-tief:#07485a;--hauch:#dcedf1;--auf-blau:#fff;
--brust:#e2660f;--brust-hauch:#fde9d9;--brust-text:#9a4107;--rot:#b3261e;
--kopf:#07485a;--kopf-text:#f2fafc;
--titel:"Bricolage",ui-rounded,-apple-system,system-ui,sans-serif;--text:-apple-system,system-ui,"Segoe UI",Roboto,sans-serif;
--tabs:58px;--unten:env(safe-area-inset-bottom,0px);color-scheme:light dark}
@media (prefers-color-scheme:dark){:root{--grund:#08161b;--flaeche:#10242b;--tinte:#e4eef1;--leise:#8ca2a9;--linie:#1f363e;
--blau:#45bcd9;--blau-tief:#8fdcee;--hauch:#143640;--auf-blau:#04222b;
--brust:#ff9248;--brust-hauch:#3b2412;--brust-text:#ffb783;--rot:#ff8a80;--kopf:#0b2a33;--kopf-text:#e4eef1}}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;min-height:100dvh;display:flex;flex-direction:column;background:var(--grund);color:var(--tinte);font:16px/1.45 var(--text);-webkit-tap-highlight-color:transparent;overflow-wrap:anywhere}
h1,h2,h3,h4,p{margin:0}
.ik{width:20px;height:20px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
a{color:var(--blau-tief)}
:focus-visible{outline:2px solid var(--blau);outline-offset:2px}

/* Kopf */
.kopf{flex:none;position:sticky;top:0;z-index:20;background:var(--kopf);color:var(--kopf-text);padding:calc(env(safe-area-inset-top,0px) + 10px) 16px 12px}
.kopf-in{max-width:720px;margin:auto;display:flex;align-items:center;gap:12px}
.marke{width:40px;height:40px;flex:none;color:var(--kopf-text)}
.kopf h1{font:700 25px/1.1 var(--titel);letter-spacing:-.015em}
.kopf p{font-size:13px;line-height:1.3;opacity:.72;margin-top:2px}

/* Inhalt */
main{flex:1;width:100%;max-width:720px;margin:0 auto;padding:16px 16px calc(var(--tabs) + var(--unten) + 28px)}
main.mit-dock{display:flex;flex-direction:column;padding-bottom:calc(var(--tabs) + var(--unten))}
body.tippt main.mit-dock{padding-bottom:0}
.abschnitt{margin-top:30px}
.abschnitt:first-child{margin-top:4px}
.abschnitt>h2{font:700 20px/1.2 var(--titel);letter-spacing:-.01em;display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin-bottom:10px}
.abschnitt>h2 small{font:500 13px/1 var(--text);color:var(--leise);letter-spacing:0}
.hinweis{color:var(--leise);font-size:14px;margin:-4px 0 12px}
.leer{color:var(--leise);font-size:15px;background:var(--flaeche);border-radius:16px;padding:16px}
.meta{font-size:13px;color:var(--leise);line-height:1.35}

/* Knöpfe und Felder */
button{font:600 15px/1 var(--titel);border:0;border-radius:12px;height:44px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;gap:8px;cursor:pointer;color:var(--blau-tief);background:var(--hauch);transition:transform .08s}
button:active{transform:scale(.96)}
button:disabled{opacity:.45}
.haupt{background:var(--blau);color:var(--auf-blau)}
.weg{background:transparent;color:var(--rot);padding:0 10px}
.rund{width:40px;height:40px;padding:0;border-radius:50%;flex:none}
.klar{background:transparent;color:var(--leise)}
label{display:block;font-size:13px;color:var(--leise);margin:12px 0 4px}
input,textarea{width:100%;font:inherit;color:var(--tinte);background:var(--grund);border:1px solid var(--linie);border-radius:10px;padding:10px 12px}
textarea{min-height:130px;display:block}
input:focus,textarea:focus{outline:0;border-color:var(--blau)}
.pille{display:inline-block;font:600 12px/1 var(--titel);padding:5px 9px;border-radius:10px;background:var(--hauch);color:var(--blau-tief);white-space:nowrap}
.pille.grau{background:var(--grund);color:var(--leise)}
.pille.warm{background:var(--brust-hauch);color:var(--brust-text)}

/* Karte und Liste */
.karte{background:var(--flaeche);border-radius:16px;padding:16px;margin-bottom:12px}
.liste{background:var(--flaeche);border-radius:16px;overflow:hidden}
.liste>*{padding:13px 16px;border-top:1px solid var(--linie)}
.liste>*:first-child{border-top:0}
.zeile{display:flex;gap:12px;align-items:flex-start}
.zeile>.ik{margin-top:2px;color:var(--blau)}
.zeile>div{flex:1;min-width:0}
.zeile>.pille{margin-top:1px}
.symbol{width:40px;height:40px;border-radius:12px;background:var(--hauch);color:var(--blau-tief);display:grid;place-items:center;flex:none}
.symbol.klein{width:32px;height:32px;border-radius:10px}
.knoepfe{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:14px}
.knoepfe .weg{margin-left:auto}
.knoepfe.breit>button{flex:1 1 auto}
.knoepfe.neben{margin-top:4px;margin-bottom:-8px}
.knoepfe.neben>button{height:40px;font-size:14px}
.knoepfe.neben>.klar{padding:0 10px;margin-left:-10px;color:var(--blau-tief)}
.knoepfe.eng>button{height:40px;padding:0 13px;font-size:14px}
.meldung{display:flex;gap:10px;align-items:flex-start;background:var(--hauch);color:var(--blau-tief);border-radius:14px;padding:12px 14px;margin-bottom:14px;font-weight:500}

/* Text aus Antworten und Zusammenfassungen */
.text p{margin-bottom:8px}
.text ul,.text ol{margin:0 0 8px;padding-left:20px}
.text li{margin:3px 0}
.text li::marker{color:var(--blau)}
.text h4{font:700 15px/1.3 var(--titel);margin:12px 0 4px}
.text code{font:13px ui-monospace,Menlo,monospace;background:var(--hauch);border-radius:5px;padding:1px 5px}
.text>:first-child{margin-top:0}
.text>:last-child{margin-bottom:0}

/* Fragen */
.tag{font:600 12px/1 var(--titel);color:var(--leise);text-align:center;margin:20px 0 10px}
.tag:first-child{margin-top:4px}
.du{margin:12px 0 0 16%;display:flex;flex-direction:column;align-items:flex-end}
.du>div{background:var(--blau);color:var(--auf-blau);border-radius:18px 18px 4px 18px;padding:10px 14px;white-space:pre-wrap}
.du time{font-size:11px;color:var(--leise);margin:4px 4px 0}
.er{margin:8px 5% 0 0;background:var(--flaeche);border-radius:18px 18px 18px 4px;padding:12px 14px 6px}
.er .laut{height:32px;padding:0 8px;margin:4px 0 0 -8px;background:transparent;color:var(--leise);font:500 13px/1 var(--text)}
.er .laut .ik{width:17px;height:17px}
.er.warte{padding-bottom:12px;color:var(--leise);display:flex;align-items:center;gap:10px}
.punkte{display:inline-flex;gap:4px}
.punkte i{width:6px;height:6px;border-radius:50%;background:var(--blau);animation:puls 1.1s infinite ease-in-out}
.punkte i:nth-child(2){animation-delay:.18s}.punkte i:nth-child(3){animation-delay:.36s}
@keyframes puls{0%,70%,100%{opacity:.25;transform:scale(.8)}35%{opacity:1;transform:scale(1)}}
.start{text-align:center;padding:26px 8px 8px}
.start .gross{width:96px;height:96px;color:var(--tinte)}
.start h2{font:700 26px/1.15 var(--titel);letter-spacing:-.015em;margin:8px 0 6px}
.start>p{color:var(--leise);max-width:34ch;margin:0 auto 18px}
.start .liste{text-align:left}
.start .zeile b{font-weight:600}
.dock{position:sticky;bottom:calc(var(--tabs) + var(--unten));z-index:5;margin-top:auto;padding:14px 0 10px;background:linear-gradient(to top,var(--grund) 84%,transparent)}
body.tippt .dock{bottom:0}
.schnell{display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;margin:0 -16px 10px;padding:0 16px}
.schnell::-webkit-scrollbar{display:none}
.schnell button{flex:none;height:34px;border-radius:17px;padding:0 13px;background:var(--flaeche);border:1px solid var(--linie);font:500 14px/1 var(--text);color:var(--tinte)}
.feld{display:flex;align-items:flex-end;gap:2px;background:var(--flaeche);border:1px solid var(--linie);border-radius:24px;padding:4px}
.feld:focus-within{border-color:var(--blau)}
.feld textarea{flex:1;min-height:0;height:40px;max-height:140px;border:0;border-radius:0;background:transparent;resize:none;padding:9px 6px}
.anhang{display:flex;align-items:center;gap:10px;background:var(--flaeche);border-radius:14px;padding:6px 6px 6px 6px;margin-bottom:8px;width:max-content;max-width:100%}
.anhang[hidden]{display:none}
.anhang img{width:52px;height:52px;object-fit:cover;border-radius:10px}
.anhang span{font-size:14px;color:var(--leise)}

/* Karten */
.kk{scroll-margin-top:96px}
.kk:target{box-shadow:0 0 0 2px var(--blau)}
.kk-kopf{display:flex;gap:12px;align-items:flex-start}
.kk-kopf>div{flex:1;min-width:0}
.kk h3{font:700 17px/1.25 var(--titel)}
.kk .meta{margin-top:3px}
.vorschau{margin-top:12px;font-size:15px}
.vorschau b{display:block;font-weight:600}
.vorschau .fakt{color:var(--leise);font-size:14px}
.vorschau .lang{white-space:pre-wrap;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden}
.felder{display:none;border-top:1px solid var(--linie);margin-top:14px;padding-top:2px}
.kk.offen .felder{display:block}
.kk.offen .vorschau{display:none}

/* iMac */
.schirm{background:#0a1d23;border-radius:14px;aspect-ratio:16/9;overflow:hidden;display:grid;place-items:center;color:#a9c3ca;font-size:14px;text-align:center;padding:0}
.schirm img{width:100%;display:block}
.schirm p{padding:0 22px}
.schirm.gross{display:block;overflow:auto;-webkit-overflow-scrolling:touch}
.schirm.gross img{width:280%;max-width:none}
.schirm-zeile{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:8px 0 0 4px}
#antw{margin:14px 0 0}

/* Gespräche */
.aufnahme h3{font:700 17px/1.25 var(--titel)}
.punkt{width:10px;height:10px;border-radius:50%;background:var(--brust)}
details>summary{list-style:none;cursor:pointer;display:flex;gap:12px;align-items:center}
details>summary::-webkit-details-marker{display:none}
details>summary>div{flex:1;min-width:0}
details>summary b{font-weight:600;display:block}
details>summary .ik{color:var(--leise);transition:transform .15s}
details[open]>summary .ik{transform:rotate(180deg)}
details .text{margin-top:12px;font-size:15px}
.zuletzt>summary h2{font:700 20px/1.2 var(--titel);letter-spacing:-.01em;margin:0;flex:1;display:flex;align-items:baseline;gap:10px}
.zuletzt>summary h2 small{font:500 13px/1 var(--text);color:var(--leise)}
.zuletzt>summary{padding:4px 0 6px}
.zuletzt[open]>summary{margin-bottom:10px}

/* Mehr */
.suchfeld{display:flex;gap:8px}
.suchfeld>div{flex:1;position:relative}
.suchfeld .ik{position:absolute;left:12px;top:12px;color:var(--leise)}
.suchfeld input{height:44px;padding-left:40px;background:var(--flaeche);border-radius:12px}
#treffer{margin-top:12px}
.treffer .oben{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-bottom:5px}
.treffer b{font-weight:600;display:block}
.treffer .adresse{display:block;font-size:14px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.treffer p{font-size:14px;color:var(--leise);margin-top:3px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
mark{background:var(--brust-hauch);color:inherit;border-radius:3px;padding:0 2px}
.routine h3{font:700 16px/1.3 var(--titel)}
.routine .wunsch{font-size:15px;margin-top:10px}
.skelett{height:14px;border-radius:7px;background:var(--linie);opacity:.7;margin:5px 0;animation:puls 1.4s infinite ease-in-out}

/* Reiterleiste */
.tabs{position:fixed;left:0;right:0;bottom:0;z-index:20;background:var(--flaeche);border-top:1px solid var(--linie);padding-bottom:var(--unten)}
@supports (backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px)){.tabs{background:color-mix(in srgb,var(--flaeche) 86%,transparent);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px)}}
.tabs-in{max-width:720px;margin:auto;display:flex;height:var(--tabs)}
.tabs a{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:var(--leise);text-decoration:none;font:600 11px/1 var(--titel)}
.tabs a i{position:relative;display:grid;place-items:center;width:54px;height:28px;border-radius:14px}
.tabs a .ik{width:23px;height:23px}
.tabs a.an{color:var(--blau-tief)}
.tabs a.an i{background:var(--hauch)}
.zahl{position:absolute;top:-4px;right:3px;min-width:18px;height:18px;border-radius:9px;background:var(--brust);color:#fff;font:700 11px/18px var(--text);text-align:center;padding:0 5px;font-style:normal}
body.tippt .tabs{display:none}

/* Meldung unten */
#toast{position:fixed;left:16px;right:16px;bottom:calc(var(--tabs) + var(--unten) + 14px);z-index:30;margin:auto;max-width:460px;background:var(--tinte);color:var(--grund);border-radius:14px;padding:12px 16px;font-size:15px;opacity:0;transform:translateY(12px);pointer-events:none;transition:opacity .2s,transform .2s}
#toast.da{opacity:1;transform:none}
#toast.fehler{background:var(--rot);color:#fff}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
@media (min-width:760px){.kopf{padding-left:24px;padding-right:24px}.du{margin-left:35%}.er{margin-right:20%}}
